INSERT OR IGNORE INTO PostTag (postId, tagId) VALUES (1433, 297);
INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1430, 'Hội Trại Tuổi Trẻ Phật Giáo 2018 | Tuổi Thanh Xuân', 'hoi-trai-tuoi-tre-phat-giao', '<p>Hội trại tuổi trẻ Phật giáo là một chương trình trại hè tổ chức hằng năm dành cho lứa tuổi thanh thiếu niên. Năm nay với chủ đề Tuổi Thanh Xuân tổ chức ở Phan Thiết là kỳ hội trại thứ 13. Đây là một cơ hội để các bạn trẻ chiêm nghiệm lại và viết tiếp một hành trình thanh xuân của tuổi trẻ. Ngoài là một sân chơi dành cho tuổi trẻ, nơi đây còn là một nơi gieo mầm hạt giống Phật pháp đến cho tuổi trẻ. Nơi đây ngoài các trò chơi vận động, giao lưu với hơn 1000 bạn trẻ. Nó còn là những buổi thiền định, những bài giảng Phật pháp chân thực vào đời sống tuổi trẻ. Bạn sẽ còn được học cách ngồi thiền, hít vào thở ra đúng cách, tái tạo năng lượng và thanh lọc những năng lượng tiêu cực từ cơ thể.</p>
<p><iframe src="https://www.youtube.com/embed/MxqOo2ui1eg" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
<h2>Nguồn gốc Hội trại tuổi trẻ Phật giáo</h2>
<p>Kỳ hội trại tuổi trẻ Phật giáo đầu tiên được tổ chức tại bãi biển Lộc An, Bà Rịa &#8211; Vũng Tàu. Chủ đề: &#8220;Đến vui về nhớ&#8221;. Ban đầu Hội trại được ban hướng dẫn Phật tử trung ương tổ chức. Sau này được tách ra và kết hợp vào các tỉnh khác nhau để tổ chức ở nhiều địa điểm.</p>
<p>Đến năm 2018, với kỳ Hội trại tuổi trẻ Phật Giáo được tổ chức ở Phan Thiết là kỳ thứ 13 và cũng là 13 năm trải qua hoạt động.</p>
<p align="left">“Sự thành công của hội trại không nằm ở sự điều động của ban tổ chức mà nằm ở sự tự giác, đồng điệu trong tâm hồn các trại sinh. Hãy học tập đức tính tốt được định hình bởi giáo lý đạo Phật, hoà mình với thiên nhiên, kết nối bạn bè khắp nơi để học tập cái hay, cái tốt của nhau” &#8211; HT.Thích Chơn Không gửi gắm đến các bạn trẻ.</p>
<h2>Những chương trình của Hội trại tuổi trẻ Phật giáo</h2>
<p>&#8211; <strong>Hội thi Phật pháp, giảng thuyết về chủ đề</strong>: Bạn sẽ có một hội thi Rung Chuông Chùa vui nhộn. Một bài thuyết giảng khoảng 1 giờ với chủ đề chính từ những vị thầy Đại Đức hoặc Hòa Thượng đáng kính.</p>
<p>&#8211; <strong>Đêm yêu thương</strong>: Đó là giây phút lắng lòng cùng những yêu thương đến cha mẹ, bạn bè. Hoa đăng được thắp lên, truyền lửa từng trại sinh. Mọi người sẽ độc hồi kinh cầu an đến người thân yêu của mình.<br />
<iframe src="https://www.youtube.com/embed/VZiUZsnIDhM" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
<p>&#8211; <strong>Ngày dựng trại và sinh hoạt</strong>: Các bạn sẽ có những khoảnh khắc trang trí trại cùng nhau. Những tiểu trại được trang trí với nhiều màu sắc và hình dáng khác nhau theo từng ý tưởng đặt ra từ chính bạn. Mỗi tiểu trại bao gồm khoảng 20 trại sinh sẽ sinh hoạt cùng một lều tự trang trí.<br />
<iframe src="https://www.youtube.com/embed/jHna-lcA7Eo" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
<p>&#8211; <strong>Trò chơi nhỏ</strong>: Toàn thể hội trại chia ra làm 4 cụm, mỗi cụm sẽ có các tiểu trại với tên gọi: Từ Bi, Tinh Tấn, Trí Tuệ, Thanh Tịnh theo số thứ tự. Trò chơi nhỏ tập họp các trò chơi để tiểu trại ganh đua nhau và &#8220;quẩy&#8221; cùng nhau.<br />
<iframe src="https://www.youtube.com/embed/dFF-kyfrUZk" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
<p>&#8211; <strong>Tham quan địa điểm trại</strong>: Mỗi năm Hội trại tiểu trẻ Phật giáo đều tổ chức ở mỗi địa điểm khác nhau. Các bạn sẽ được tham quan tự do địa điểm. Đó có thể là tắm biển, hoặc leo núi tùy vào địa điểm tham quan.<br />
<iframe src="https://www.youtube.com/embed/qUT5IIlO4u0" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
<p>&#8211; <strong>Đêm lửa trại</strong>: Đây là một đêm náo nhiệt nhất. Các bạn sẽ tập họp trình diễn những tiết mục văn nghệ được chọn lọc sau khi thi. Mọi người sẽ được lắng nghe những khách mời là những ca sĩ nổi tiếng trong các cuộc thi The Voice hay Việt Nam Idols. Đặc biệt thực đơn chính là màn đốt lửa trại, mọi người quây quần hát ca. Cùng nhau chơi những trò chơi nhỏ trong lửa trại.<br />
<iframe src="https://www.youtube.com/embed/DVAfig89OCU" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
<p>&#8211; <strong>Thiền định</strong>: Sáng hôm sau mọi người sẽ thức sớm. Những bậc Đại Đức hoặc Hòa Thượng sẽ hướng dẫn các bạn thiền định trong. Thiền định để tâm hồn nhẹ nhàng, tập trung năng lượng và loại bỏ tạp niệm. Các bạn sẽ được đi bộ nhẹ nhàng xung quanh khu đất trại. Đó có thể là chuyến đi dọc bờ biển hoặc đi dọc theo những ngọn đồi tùy địa điểm.<br />
<iframe src="https://www.youtube.com/embed/eBvyONPRdjM" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
<p>&#8211; <strong>Trò chơi lớn</strong>: Các bạn sẽ được chia thành 4 cụm trại và chơi những trò chơi lớn theo team building. Những trò chơi tạo sự đoàn kết và vô cùng gay cấn. Hội Trại hàng năm được tổ chức vào tuần thứ 3 của tháng 7 dương lịch.<br />
<iframe src="https://www.youtube.com/embed/xmo-7k9GvZs" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
<h3>Những kỳ Hội trại tuổi trẻ Phật giáo từng được tổ chức</h3>
<p>1. Hội trại Tuổi trẻ Phật giáo lần I &#8211; năm 2006 tại bãi biển Lộc An, Bà Rịa &#8211; Vũng Tàu. Chủ đề: &#8220;Đến vui về nhớ&#8221;.</p>
<p>2. Hội trại Tuổi trẻ Phật giáo lần II &#8211; năm 2007 tại Khu du lịch Hồ Tràm, Bà Rịa &#8211; Vũng Tàu. Chủ đề: “Sống trọn niềm vui”.</p>
<p>3. Hội trại Tuổi trẻ Phật giáo lần III &#8211; năm 2008 tại khu du lịch Thác Giang Điền, Đồng Nai. Chủ đề: “Niềm tin cuộc sống”.</p>
<p>4. Hội trại Tuổi trẻ Phật giáo lần IV &#8211; năm 2009 tại khu du lịch Thác Giang Điền, Đồng Nai. Chủ đề: “Mãi mãi một niềm vui”.</p>
<p>5. Hội trại Tuổi trẻ Phật giáo lần V &#8211; năm 2010 tại khu du lịch Minh Trí, Xuyên Mộc, Bà Rịa &#8211; Vũng Tàu. Chủ đề: “Hội tụ khát vọng”.</p>
<p>6. Hội trại Tuổi trẻ Phật giáo lần VI &#8211; năm 2011 tại khu du lịch Vườn Xoài, TP. Biên Hòa, Đồng Nai. Chủ đề: “Tiếp bước an vui”.</p>
<p>7. Hội trại Tuổi trẻ Phật giáo lần VII &#8211; năm 2012 tại khu du lịch Madagui, Lâm Đồng. Chủ đề: “Kết nối yêu thương”.</p>
<p>8. Hội trại Tuổi trẻ Phật giáo lần VIII &#8211; năm 2013 tại khu du lịch Paraside, TP. Vũng Tàu. Chủ đề “Khơi nguồn an lạc”.</p>
<p>9. Hội trại Tuổi trẻ Phật giáo lần IX &#8211; năm 2014 tại KDL Kawasami, Long Hải, tỉnh Bà Rịa Vũng Tàu. Chủ đề “Sáng mãi niềm tin”.</p>
<p>10. Hội trại Tuổi trẻ Phật giáo lần X &#8211; năm 2015 tại KDL Đambri, TP. Bảo Lộc, tỉnh Lâm Đồng với chủ đề &#8220;Khát vọng bay cao&#8221;.</p>
<p>11- Hội trại tuổi trẻ phật giáo lần thứ XI năm 2016 tại Ocean Dunes Resort, TP. Phan Thiết Chủ đề “Khơi nguồn yêu thương”.</p>
<p>12. Hội trại Tuổi trẻ Phật giáo lần XII- 2017 tại khu Zenna Pool Camp, huyện Long Điền và chùa Đại Tòng Lâm, huyện Tân Thành, tỉnh BRVT. Chủ đề “Sống tử tế”.</p>
<p>13 – Hội trại Tuổi trẻ Phật giáo lần thứ XIII năm 2018 tại Chùa Bửu Sơn và Khu du lịch Bồng lai TP Phan Thiết chủ đề “Tuổi thanh xuân”.</p>
<h3>Từ quá trình chuẩn bị kỳ công trước 3 tháng</h3>
<p>Đại đức Thích An Đạt &#8211; Linh hồn của Hội trại hàng năm, là người đứng sau chỉ huy các kỳ hội trại tâm sự:</p>
<p><em>&#8220;Đó là thời gian của việc đi tìm địa điểm, lên kế hoạch, xin phép nhà chức trách, tính toán kinh phí, xin tài trợ bằng những chuyến đi tiền trạm biền biệt, bất kể ngày đêm, nắng mưa của đất trời.</em></p>
<p><em>Đó là thời gian thông báo, tuyển tình nguyên viên, tập huấn, họp hành, phân công nhiệm vụ, giám sát và thảo luận các ý tưởng với anh, chị Ban quản trại.</em></p>
<p><img loading="lazy" decoding="async" class="size-full wp-image-1372" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo165.jpg" alt="Hội trại tuổi trẻ phật giáo" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo165.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo165-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /></p>
<p>Đại Đức Thích An Đạt phát biểu</p>
<p><em>Đó là thời gian vận động đầu này đầu kia để đủ kinh phí, vật dụng tổ chức, tính toán chuyện xe cộ, an ninh nơi đất trại, các điều kiện cần thiết đảm bảo cho sinh hoạt hàng ngàn người lúc hội ngộ.</em></p>
<p><em>Đó còn là khoảng thời gian giải quyết các vấn đề phát sinh, làm đầu tàu và truyền lửa để những người cộng sự cùng nhìn về một hướng, quyết tâm, chung sức chung lòng làm nên những điều kì diệu nơi đất trại để trại sinh được tận hưởng không khí trại trọn vẹn nhất.&#8221;</em></p>
<p><figure id="attachment_1240" aria-describedby="caption-attachment-1240" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1240" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo33.jpg" alt="Hội trại tuổi trẻ phật giáo" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo33.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo33-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1240" class="wp-caption-text">Rất nhiều con người đã tạo nên một kỳ hội trại thành công</figcaption></figure></p>
<h4><em><strong>Kỳ hội trại tuổi trẻ Phật giáo được hình thành từ:</strong></em></h4>
<p>Ban quản trại phải chạy đôn chạy đáo tìm những tình nguyện viên, huy động những nguồn lực cho Hội Trại.</p>
<p>Hàng chục tiểu trại trưởng làm việc với những quy trình, quy định nghiệm ngặt. Họ phải trải qua những cuối tuần tập huấn khắc khe từ hội trại. Những việc quản lý trại sinh, cách sinh hoạt cho đến những việc liên quan lịch trình đi hội trại và liên hệ ban tổ chức khi hội trại bắt đầu.</p>
<p><figure id="attachment_1210" aria-describedby="caption-attachment-1210" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1210" src="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo3.jpg" alt="Hội trại tuổi trẻ phật giáo" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo3.jpg 920w, https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo3-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1210" class="wp-caption-text">Những bạn Tiểu trại trưởng trong hành trình Hội trại tuổi trẻ Phật giáo</figcaption></figure></p>
<p>Những bạn team game phải lên những kế hoạch game khác nhau. Các bạn ấy trải qua những ngày nắng mưa trên đất trại để test game, mang đến niềm vui cho trại sinh trong thời tiết thất thường của tháng 6, tháng 7.</p>
<p>Những bạn team văn nghệ chuẩn bị sân khấu, lên kế hoạch chương trình. Từ khâu âm thanh đến hình ảnh phải là tuyệt vời nhất. Hay đến việc cầm cân nảy mực tuyển ra những tiết mục xuất sắc.</p>
<p><figure id="attachment_1299" aria-describedby="caption-attachment-1299" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1299" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo92.jpg" alt="Hội trại tuổi trẻ phật giáo" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo92.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo92-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1299" class="wp-caption-text">Những tiết mục văn nghệ được chuẩn bị kỹ lưỡng</figcaption></figure></p>
<p>Những bạn team y tế trực nhất 24/7 để phục vụ trại sinh và những tình nguyện viên.</p>
<p>Những bạn truyền thông phải cật lực làm việc quảng bá hội trại. Truyền tải những tấm hình, những thông điệp tốt nhất đến trại sinh và những bạn chưa phải là trại sinh.</p>
<p>Những bạn hậu cần, những cô chú nấu ăn phải cật lực thức đêm khuya chuẩn bị thức ăn cho hàng ngàn trại sinh. Những bữa ăn phải tự nấu với đầy đủ chuẩn mực về dinh dưỡng.</p>
<p>Những bạn trong ban kỷ lục phải luôn tuân thủ những điều kiện quản lý nghiệm ngặt. Tạo những sự bảo vệ từ bên trong lẫn bên ngoài cho trại sinh. Những bạn hy sinh về mặt hình ảnh phục vụ cho ngày hội trại.</p>
<p><figure id="attachment_1426" aria-describedby="caption-attachment-1426" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1426" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-219.jpg" alt="Hội trại tuổi trẻ phật giáo" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-219.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-219-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1426" class="wp-caption-text">Đại Đức Thích Trí Chơn nhận huy hiệu logo hội trại.</figcaption></figure></p>
<p>Ngoài ra còn rất nhiều bạn không để tên, làm những việc khác nhau phục vụ hội trại.</p>
<p>Với hơn 3 tháng làm việc cùng hơn 100 con người. Họ đã tạo nên một kỳ hội trại thành công với bao công sức đổ ra. Nhưng thành quả ấy mang lại vô cùng to lớn cho hơn 1000 con người với hạt mầm sống tốt được gieo trồng trong tâm hồn.</p>
<h2>Chủ đề tuyệt vời Tuổi Thanh Xuân với tuổi trẻ</h2>
<p>Tuổi trẻ không phải ai cũng sống với một thanh xuân rực rỡ đúng ý nghĩa. Chủ đề Hội trại năm 2018 với tựa đề Tuổi Thanh Xuân đã thật sự đánh đúng vào thực tại tâm hồn nhiều bạn trẻ. Bạn đã từng trải qua thanh xuân như thế nào hoặc thanh xuân tiếp theo của bạn là gì? Bạn sẽ dành những gì cho thanh xuân. Đây là chủ đề giáo dục giới trẻ và mang nhiều ý nghĩa Phật pháp gửi gắm vào nó.</p>
<p><figure id="attachment_1215" aria-describedby="caption-attachment-1215" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1215 size-full" src="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo8.jpg" alt="Thư gửi yêu thương tuổi thanh xuân" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo8.jpg 920w, https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo8-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1215" class="wp-caption-text">Thư gửi yêu thương tuổi thanh xuân</figcaption></figure></p>
<p><em><strong>Hội trại tuổi trẻ Phật giáo cũng là một phần trong dấu ấn thanh xuân</strong></em> của từng trại sinh. Khi đến với Hội trại các bạn ấy đã được trải qua một đêm yêu thương với những cơn mưa rào, những hoa đăng thắp sáng.</p>
<p><figure id="attachment_1225" aria-describedby="caption-attachment-1225" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1225" src="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo18.jpg" alt="Hội trại tuổi trẻ phật giáo" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo18.jpg 920w, https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo18-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1225" class="wp-caption-text">Hội Trại Tuổi Trẻ Phật Giáo</figcaption></figure></p>
<p>Những con người ấy đã cùng nhau đọc những bức thư đầy tâm tư và trải qua một đêm văn nghề đầy nụ cười và nước mắt.</p>
<p><figure id="attachment_1226" aria-describedby="caption-attachment-1226" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1226" src="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo19.jpg" alt="Hội trại tuổi trẻ phật giáo" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo19.jpg 920w, https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo19-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1226" class="wp-caption-text">Hội trại tuổi trẻ phật giáo</figcaption></figure></p>
<p>Những con người ấy đã cùng nhau trang trí nên những lều trại cực ngầu, cùng nhau chơi ma sói xuyên đêm. Hoặc là ngủ ngáy khò khò bên cạnh nhau. Sáng thức dậy đôi chân gác lên đầu người khác cũng là một cảm xúc khác lạ.</p>
<p><figure id="attachment_1373" aria-describedby="caption-attachment-1373" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1373 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo166.jpg" alt="Trại sinh hội trại tuổi trẻ phật giáo" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo166.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo166-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1373" class="wp-caption-text">Trại sinh hội trại tuổi trẻ phật giáo</figcaption></figure></p>
<p>Những con người ấy đã trải qua một đêm văn nghệ với những tiết mục tuyệt vời: múa võ nhạc, dân vũ, những bài ca truyền cảm, những điệu nhảy dance tuyệt vời hay hai ca sĩ khách mời Bảo Anh (The Voice) và Phạm Anh Duy (The Voice).</p>
<p><figure id="attachment_1300" aria-describedby="caption-attachment-1300" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1300" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo93.jpg" alt="Hội trại tuổi trẻ phật giáo" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo93.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo93-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1300" class="wp-caption-text">Bảo Anh ở Hội trại tuổi trẻ phật giáo</figcaption></figure></p>
<p>Những con người ấy dù xa lạ hay thân thuộc đã cùng nhau nắm tay, bên nhau trong một đêm lửa trại tuyệt vời.</p>
<p><figure id="attachment_1303" aria-describedby="caption-attachment-1303" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1303 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo96.jpg" alt="Mọi người hân hoan bên lửa trại" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo96.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo96-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1303" class="wp-caption-text">Mọi người hân hoan bên lửa trại</figcaption></figure></p>
<p>Những con người ấy đã ngồi thiền cùng nhau trong cái nắng sớm với sương mai lúc 6h sáng. Họ cùng nhau đi nhẹ nhàng trên những bậc thềm, bãi cát hướng về bãi biển với ánh bình minh ló dạng.</p>
<p><figure id="attachment_1309" aria-describedby="caption-attachment-1309" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1309 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo102.jpg" alt="Trại sinh tập trung ngồi thiền ở hội trại" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo102.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo102-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1309" class="wp-caption-text">Trại sinh tập trung ngồi thiền ở hội trại</figcaption></figure></p>
<p>Họ cùng nhau xây dựng nên những khoảnh khác thanh xuân cùng nhau tuyệt vời.</p>
<h3>Chúng ta học được gì từ Hội trại tuổi trẻ Phật giáo</h3>
<h4><em><strong>Phật pháp nhiệm màu</strong></em></h4>
<p>Chúng ta sẽ được trải lòng với những lời dạy từ bậc Đại đức hay Hòa thượng. Những lý niệm Phật pháp truyền tải đến những bạn trẻ không phải hoàn toàn qua lý niệm. Mà là những buổi nói chuyện sâu sắc cùng nhau. Bạn cũng có thể trao đổi với nhau qua những câu hỏi.</p>
<p><figure id="attachment_1425" aria-describedby="caption-attachment-1425" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1425 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-218.jpg" alt="Một trại sinh hỏi về phật pháp trong hội trại" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-218.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-218-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1425" class="wp-caption-text">Một trại sinh hỏi về phật pháp trong hội trại</figcaption></figure></p>
<p>Bạn sẽ học được qua những buổi thiền định, đi bộ thanh tịnh vào buổi sáng. Học cách xả những năng lượng tiêu cực từ bên trong và hít và những điều tốt đẹp để cơ thể khỏe mạnh hơn.</p>
<h4><em><strong>Bài học tuổi thanh xuân</strong></em></h4>
<p>Bạn sẽ được trải nghiệm một tuổi trẻ rực rỡ và náo động từ những con người trẻ. Hòa mình vào những điều tuyệt vời với một năng lượng tích cực từ thanh xuân của bạn.</p>
<p><figure id="attachment_1412" aria-describedby="caption-attachment-1412" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1412 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-205.jpg" alt="Trại sinh vui vẻ ở Hội trại tuổi trẻ phật giáo phan thiết" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-205.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-205-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1412" class="wp-caption-text">Trại sinh vui vẻ ở Hội trại tuổi trẻ phật giáo phan thiết</figcaption></figure></p>
<p>Bạn được rèn luyện cơ thể với những trò chơi khác nhau từ trí tuệ đến thể xác. Bạn sẽ tập trung những giá trị tinh tế của mình cho những trò chơi lầy lội trong những trò chơi lớn và nhỏ.</p>
<p><figure id="attachment_1400" aria-describedby="caption-attachment-1400" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1400 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo193.jpg" alt="Trò chơi lớn" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo193.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo193-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1400" class="wp-caption-text">Trò chơi lớn</figcaption></figure></p>
<p>Bạn sẽ học được cách giao tiếp với những người xa lạ. Bạn sẽ biết cách đoàn kết để tạo nên một nguồn lực lớn lao hơn. Hãy cùng trại của mình dùng hết sức để đạt những phần thưởng hay đơn giản là được hết mình với tuổi trẻ trong 3 ngày 2 đêm.</p>
<p><figure id="attachment_1349" aria-describedby="caption-attachment-1349" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1349 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo142.jpg" alt="Trại sinh thể hiện sự đoàn kết" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo142.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo142-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1349" class="wp-caption-text">Trại sinh thể hiện sự đoàn kết</figcaption></figure></p>
<h4><em><strong>Cơ hội giao lưu cùng những người bạn cũ lẫn mới</strong></em></h4>
<p>Hội trại tuổi trẻ Phật giáo là những ngày lầy lội cùng hơn 1000 con người khác nhau. Bạn sẽ được ăn ngủ cùng 20 người trong một tiểu trại. Bạn sẽ cùng chơi game cùng hơn 1000 con người trong những cụm trại khác nhau bao gồm Tinh Tấn, Từ Bi, Trí Tuệ và Thanh Tịnh.</p>
<p><figure id="attachment_1347" aria-describedby="caption-attachment-1347" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1347" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo140.jpg" alt="Hội trại tuổi trẻ phật giáo" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo140.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo140-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1347" class="wp-caption-text">Hội trại tuổi trẻ phật giáo</figcaption></figure></p>
<p>Bạn sẽ được nắm tay những người xa lạ, cùng trao những cái ôm nồng cháy tự nguyện. Bạn sẽ được nói nhiều hơn, cùng trò chuyện nhiều hơn cùng những người xa lạ. Đây cũng là cơ hội cho bạn tỏa sáng chính mình sau nhiều năm &#8220;chìm&#8221; đâu đó.</p>
<h4><em><strong>Đảm đang hơn với những &#8220;nghề&#8221; mới</strong></em></h4>
<p>Nói nghề thì hơi phóng đại. Nhưng chắc chắc bạn sẽ được học cách trang trí trại là thế nào: cùng đóng đinh, cột dây thun, thổi bong bóng, thắt chỉ. Hay đơn giản là những chuyện phục vụ ăn uống cho mình như gọt ổi, xoài, bưởi,&#8230; Nó sẽ khơi dậy những sự khéo léo tiềm ẩn trong bạn đã bị ngủ quên trong nhiều năm.</p>
<p><figure id="attachment_1253" aria-describedby="caption-attachment-1253" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1253 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo46.jpg" alt="Chuẩn bị trang trí trại" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo46.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo46-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1253" class="wp-caption-text">Chuẩn bị trang trí trại</figcaption></figure></p>
<h4><em><strong>Nó là một chuyến du lịch thú vị</strong></em></h4>
<p>Tại sao bạn không nghĩ nó là một chuyến du lịch thú vị nhĩ? Bạn được tham quan một địa điểm nổi tiếng. Mỗi năm hội trại sẽ đến những nơi khác nhau. Đó sẽ là một ngôi chùa lớn, một địa điểm tham quan xinh đẹp với biển, núi hay điều gì đó đặc biệt. Bạn sẽ có thời gian tắm biển, leo núi hay cả hai. Hãy cứ thưởng thức chuyến đi một cách tuyệt vời nhất.</p>
<p><figure id="attachment_1286" aria-describedby="caption-attachment-1286" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1286 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo79.jpg" alt="Khung cảnh xinh đẹp của khu cắm trại" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo79.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo79-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1286" class="wp-caption-text">Khung cảnh xinh đẹp của khu cắm trại</figcaption></figure></p>
<h3>Kết thúc không phải là hết mà là bắt đầu kỳ trại 14</h3>
<p>Một kỳ trại kết thúc, chúng ta lại cùng ôm nhau với những nụ cười và nước mặt. Họ phải chia tay những con người 3 ngày trước là xa lạ nhưng 3 ngày sau là thân quen. Họ cùng nhau trải qua hành trình 3 ngày với nhiều ý nghĩa. Nước mắt rơi không là hối tiếc mà là sự trân trọng với tình cảm dành cho nhau.</p>
<p><figure id="attachment_1211" aria-describedby="caption-attachment-1211" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1211 size-full" src="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo4.jpg" alt="Chong Chóng Màu - Vật Dụng Trang Trí Nổi Bật" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo4.jpg 920w, https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo4-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1211" class="wp-caption-text">Chong Chóng Màu &#8211; Vật Dụng Trang Trí Nổi Bật</figcaption></figure></p>
<p>Kỳ hội trại 14 năm sau sẽ vẫn tổ chức vào tháng 7. Các bạn hãy cùng đón chờ thông tin mới về địa điểm và thời gian chính thức bắt đầu nhé! Hãy chờ mong những điều mới từ Hội trại tuổi trẻ phật giáo năm 2019.</p>
<p>Nhìn lại tất cả hoạt động Hội trại tuổi trẻ Phật giáo năm 2018 bạn nhé:<br />
<iframe src="https://www.youtube.com/embed/6c1puPinnP4" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
<p>Những hình ảnh khoảnh khắc đặc biệt trong Hội Trại:</p>
<p><figure id="attachment_1415" aria-describedby="caption-attachment-1415" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1415 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-208.jpg" alt="Mọi người vui vẻ sinh hoạt khóa tu mùa hè" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-208.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-208-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1415" class="wp-caption-text">Mọi người vui vẻ sinh hoạt khóa tu mùa hè</figcaption></figure></p>
