INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1186, 'Cerberus &#8211; Chú chó canh giữ địa ngục', 'cerberus', '<p>Cerberus là một quái vật trong thần thoại Hy Lạp. Nó là một con chó nhiều đầu bảo vệ cổng của địa ngục. Nó ngăn người chết rời khỏi và chặn những kẻ xâm nhập bất hợp pháp. Cerberus thường được nhắc đến qua câu chuyện của Heracles.</p>
<h3>Cerberus &#8211; Chú chó canh giữ địa ngục</h3>
<p><figure id="attachment_1190" aria-describedby="caption-attachment-1190" style="width: 400px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1190" src="https://media.huynhhieutravel.com/Cerberus2.jpg" alt="Cerberus" width="400" height="225" srcset="https://media.huynhhieutravel.com/Cerberus2.jpg 1280w, https://media.huynhhieutravel.com/Cerberus2-768x432.jpg 768w" sizes="(max-width: 400px) 100vw, 400px" /><figcaption id="caption-attachment-1190" class="wp-caption-text">Cerberus</figcaption></figure></p>
<p>Cerberus được miêu tả khác nhau với nhiều dị bản. Nhưng điều chắc chắn là hinh dạng của nó giống như một con chó.</p>
<h4>Hình dạng của Cerberus</h4>
<p><img loading="lazy" decoding="async" class="alignnone size-full wp-image-1196" src="https://media.huynhhieutravel.com/Cerberus-title.jpg" alt="" width="851" height="200" srcset="https://media.huynhhieutravel.com/Cerberus-title.jpg 851w, https://media.huynhhieutravel.com/Cerberus-title-768x180.jpg 768w" sizes="(max-width: 851px) 100vw, 851px" /></p>
<p>Thường có nhiều tranh cãi về số đầu của Cerberus. Nhưng đa số đều cho rằng nó có 3 đầu. Nó là kết quả của hai quái vật là Echidna và Typhon (Những quái vật sinh ra để hủy diệt Olympus &#8211; Nữa người nữa rắn với thân trên là người). Ngoài ra một số giả thuyết khác cho rằng sở dĩ nó có ba chiếc đầu là vì mỗi chiếc đầu tượng trưng cho quá khứ, hiện tại và tương lai.</p>
<p><figure id="attachment_1191" aria-describedby="caption-attachment-1191" style="width: 400px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1191 size-full" src="https://media.huynhhieutravel.com/Cerberus3.jpg" alt="Cerberus" width="400" height="300" /><figcaption id="caption-attachment-1191" class="wp-caption-text">Cerberus</figcaption></figure></p>
<p>Trong mô tả sớm nhất của Cerberus, Hesiod&#8217;s Theiodony (Khoảng thế kỷ thứ 8 đến thứ 7 TCN), Cerberus có năm mươi đầu. Trong khi Pindar (khoảng năm 522 &#8211; 443 TCN) cho rằng nó có 100 cái đầu. Tuy nhiên, các nhà văn sau này hầu như đều mô tả nó với ba cái đầu.</p>
<p>Trong nghệ thuật, Cerberus thường được mô tả với hai đầu chó, không bao giờ nhiều hơn ba, nhưng đôi khi chỉ có một. Một trong hai mô tả sớm nhất (Khoảng năm 590–580 TCN), một chiếc cốc Corinth từ Argos, nó được thể hiện như một con chó bình thường. Sự xuất hiện đầu tiên của một con Cerberus ba đầu xảy ra ở giữa thế kỷ thứ 6 TCN.</p>
<p>Ngoài ra con nhiều giả thuyết về số đầu hoặc đầu của Cerberus là đầu rắn. Dựa trên giả thuyết cha mẹ của nó đều là những quái vật mình người thân rắn.</p>
<h4>Câu chuyện về Cerberus</h4>
<p><img loading="lazy" decoding="async" class="alignnone size-full wp-image-1197" src="https://media.huynhhieutravel.com/Cerberus-title2.jpg" alt="" width="851" height="200" srcset="https://media.huynhhieutravel.com/Cerberus-title2.jpg 851w, https://media.huynhhieutravel.com/Cerberus-title2-768x180.jpg 768w" sizes="(max-width: 851px) 100vw, 851px" /></p>
<p>Thần thoại duy nhất về Cerberus liên quan đến việc nó bị bắt bởi Heracles. Eurystheus đưa ra nhiệm vụ thứ 12 &#8211; cũng là nhiệm vụ cuối cùng để Heracles thực hiện. Đây là một nhiệm vụ khó khăn mà Eurystheus nghĩ rằng Heracles sẽ không thể thực hiện được.</p>
<p>Hera mớm lời cho Eurystheus: &#8220;Hãy yêu cầu hắn ta xuống địa ngục mà không đem theo bất cứ một thứ vũ khí nào!&#8221;. Tuy nhiên, Hercules đã xin được mang theo bộ da của con sư tử Némée.</p>
<p>Gần đến Địa ngục, Hercules bắt gặp Theseus và Pirithous bị xích vào một tảng đá. Chàng cứu được Theseus nhưng khi định kéo Pirithous lên thì mặt đất rung chuyển dữ dội. Do Pirithious chính là người chủ mưu bắt cóc nàng Persephone &#8211; vợ của Hades.</p>
<p><figure id="attachment_1192" aria-describedby="caption-attachment-1192" style="width: 400px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1192" src="https://media.huynhhieutravel.com/Cerberus4.jpg" alt="Cerberus" width="400" height="400" srcset="https://media.huynhhieutravel.com/Cerberus4.jpg 425w, https://media.huynhhieutravel.com/Cerberus4-150x150.jpg 150w" sizes="(max-width: 400px) 100vw, 400px" /><figcaption id="caption-attachment-1192" class="wp-caption-text">Cerberus mô hình hoạt họa</figcaption></figure></p>
<p>Trở ngại đầu tiên khi muốn xuống địa phủ là phải vượt qua con sông Styx. Nơi những linh hồn của người vừa chết tụ tập chờ đợi để được qua sông trên chiếc thuyền của Charon. Charon sẽ không đưa bất cứ ai qua sông nếu họ chưa hội đủ hai điều kiện sau. Đầu tiên là phải đưa một khoản lộ phí dưới dạng một đồng tiền hình con dê. Hai là người đó đã chết. Hercules không đáp ứng được điều kiện nào. Một trường hợp làm vấn đề thêm trầm trọng với bản tính cáu kỉnh của Charon. Nhưng Hercules chỉ cần vỗ tay là đủ để Charon ngoan ngoãn đưa chàng vượt sông Styx.</p>
<p>Thử thách lớn hơn chính là con Cerberus, với hàm răng sắc nhọn, ba cái đầu, một con rắn độc ở đằng đuôi. Tất cả nhằm vào Hercules khi con nó bất thình lình lao tới chụp vào cổ chàng. May thay, Hercules khoác tấm da con sư tử chàng đã giết trước đây nên không gì có thể xuyên thủng được ngoại trừ sấm sét của Zeus. Hercules cuối cùng cũng quy phục được con Cerberus và lôi nó tới Tiryns. Nơi chàng được tự do sau nhiệm vụ cuối cùng này.</p>
<p>Sau khi tên Eurystheus hoảng sợ năn nỉ chàng đem con chó trở về Địa ngục. Hercules thả con Cerberus trở về. Nó khiếp sợ nhưng cũng rất căm giận nên đã tự tử.</p>
<h4>Biểu tượng Cerberus</h4>
<p>Biểu tượng Cerberus là một biểu tượng thông dụng trong nghệ thuật Hy Lạp và La Mã cổ đại. Những hình tượng này bắt đầu xuất hiện từ thế kỷ thứ 6 TCN. Hình ảnh Cerberus được vẽ lên một chén Corinth (khoảng 590–580 trước Công nguyên). Trên chén Corinth là những hình vẽ kể về hành trình Hercules xuống địa ngục bắt nó.</p>
<p>Đa phần những biểu tượng Cerberus đều là câu chuyện kể về hành trình của Hercules với nhiều biến thể khác nhau. Chúng được khắc trên những bình gốm hay trên mái của một công trình nào đó.</p>
<p>Trong chòm sao Cerberus được giới thiệu bởi Johannes Hevelius năm 1687, nó được vẽ như một con rắn ba đầu, được giữ trong tay Hercules (trước đây những ngôi sao này đã được mô tả như một nhánh cây mọc trên cây Táo của Hesperides).</p>
<p><figure id="attachment_1189" aria-describedby="caption-attachment-1189" style="width: 400px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1189" src="https://media.huynhhieutravel.com/Cerberus.jpg" alt="Cerberus" width="400" height="244" srcset="https://media.huynhhieutravel.com/Cerberus.jpg 1200w, https://media.huynhhieutravel.com/Cerberus-768x468.jpg 768w" sizes="(max-width: 400px) 100vw, 400px" /><figcaption id="caption-attachment-1189" class="wp-caption-text">Hình tượng Cerberus trong Harry Potter</figcaption></figure></p>
<p>Hình tượng Cerberus còn được nhắc đến đến trong Harry Potter với cái tên Fluffy. Nó là con chó canh giữ cổng đường vào căn hầm giữ Hòn đá Phù thủy.</p>
', 'Cerberus là một quái vật trong thần thoại Hy Lạp. Nó là một con chó nhiều đầu bảo vệ cổng của địa ngục. Nó ngăn người chết rời khỏi và chặn những kẻ xâm nhập bất hợp pháp. Cerberus thường được nhắc đến qua câu chuyện của Heracles. Cerberus &#8211; Chú chó canh giữ địa ngục [&hellip;]', 1190, 'post', '2018-07-18 09:33:18', '2023-04-23 12:33:46');
